use vstd::prelude::*;

verus! {
    // Given a non‐empty vector `a` of i8’s, return the index of the first minimal element.
    // Post‐conditions:
    //   1) result < a.len()
    //   2) for all j < a.len(): a[result] <= a[j]
    //   3) for all j < result: a[j] > a[result]
    fn nanargmin(a: Vec<i8>) -> (result: usize)
        requires
            a.len() > 0,
        ensures
            result < a.len(),
            forall(|j: usize| j < a.len() ==> a[result] <= a[j]),
            forall(|j: usize| j < result ==> a[j] > a[result]),
    {
        // We scan from i = 1 up to a.len(), keeping min_idx < i
        let mut min_idx: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant
                // i runs from 1 to a.len()
                1 <= i && i <= a.len(),
                // at each step, min_idx < i
                min_idx < i,
                // among indices [0..i), a[min_idx] is minimal
                forall(|j: usize| j < i ==> a[min_idx] <= a[j]),
                // and it is the *first* occurrence of that minimum
                forall(|j: usize| j < min_idx ==> a[j] > a[min_idx]),
            decreases a.len() - i,
        {
            let curr_i = i;
            if a[curr_i] < a[min_idx] {
                // we found a strictly smaller element at curr_i
                let old = min_idx;
                // witness the strict inequality
                assert(a[curr_i] < a[old]);
                // now show that for all j < curr_i, a[j] > a[curr_i],
                // so curr_i becomes the first occurrence of the new minimum
                assert(forall(|j: usize| j < curr_i ==> a[j] > a[curr_i])) by {
                    // from the old invariant: for all j < curr_i, a[old] <= a[j]
                    assert(forall(|j: usize| j < curr_i ==> a[old] <= a[j]));
                    // and we know a[curr_i] < a[old]
                    assert(a[old] > a[curr_i]);
                    // hence for all j < curr_i: a[j] > a[curr_i]
                    assert(forall(|j: usize| j < curr_i ==> a[j] > a[curr_i]));
                }
                min_idx = curr_i;
            }
            // Whether or not we updated min_idx, we must show
            // for all j < curr_i, a[min_idx] <= a[j].
            // In the update‐case we have just proved it;
            // in the no‐update case it follows from the old invariant.
            assert(forall(|j: usize| j < curr_i ==> a[min_idx] <= a[j]));
            // And also for j = curr_i itself:
            assert(a[min_idx] <= a[curr_i]);

            // Advance i
            i = curr_i + 1;

            // Re‐establish the "minimal among seen" invariant for the new i:
            // forall j < i: a[min_idx] <= a[j]
            assert(forall(|j: usize| j < i ==> a[min_idx] <= a[j])) by {
                // split into j < curr_i and j = curr_i
                assert(forall(|j: usize| j < curr_i ==> a[min_idx] <= a[j]));
                assert(a[min_idx] <= a[curr_i]);
                assert(forall(|j: usize| j < i ==> a[min_idx] <= a[j]));
            }
        }
        result = min_idx;
    }
}

